package Java;

public class WhileLoopDemo {

	private static int count;

	public static void main(String[] args) {
		// TODO Auto-generated method stub
          
		int count = 1;
		
		System.out.println("WHILE LOOP");
		
		while(count<20) {
			 System.out.println("Display the value of count:" +count);
			 count++;
		}//end of while loop
		
		
		
		
	}// end of main method

}//end of the class
